using System;
using System.Collections.Generic;
using Betta.Attributes;
using Rhino.Geometry;

namespace BenchPlugin
{
    /// <summary>One four-sided facade panel. Opaque: travels on one "Panel" wire.</summary>
    [GrasshopperOpaque]
    public class Panel
    {
        public Panel() : this(Point3d.Origin, Point3d.Origin, Point3d.Origin, Point3d.Origin, 0) { }

        public Panel(Point3d a, Point3d b, Point3d c, Point3d d, int index)
        {
            Corners = new[] { a, b, c, d };
            Index = index;
        }

        public Point3d[] Corners { get; }
        public int Index { get; }

        public Curve Outline =>
            new PolylineCurve(new[] { Corners[0], Corners[1], Corners[2], Corners[3], Corners[0] });

        /// <summary>Area of the quad (half the cross product of its diagonals).</summary>
        public double Area =>
            0.5 * Vector3d.CrossProduct(Corners[2] - Corners[0], Corners[3] - Corners[1]).Length;

        /// <summary>Distance from the fourth corner to the plane through the other three.</summary>
        public double PlanarityDeviation
        {
            get
            {
                var n = Vector3d.CrossProduct(Corners[1] - Corners[0], Corners[2] - Corners[0]);
                if (!n.Unitize()) return 0;
                return Math.Abs(n * (Corners[3] - Corners[0]));
            }
        }

        public Point3d Center => new Point3d(
            (Corners[0].X + Corners[1].X + Corners[2].X + Corners[3].X) / 4,
            (Corners[0].Y + Corners[1].Y + Corners[2].Y + Corners[3].Y) / 4,
            (Corners[0].Z + Corners[1].Z + Corners[2].Z + Corners[3].Z) / 4);

        public double Edge(int i) => Corners[i].DistanceTo(Corners[(i + 1) % 4]);

        /// <summary>Mean of the first and third edge lengths.</summary>
        public double Width => (Edge(0) + Edge(2)) / 2;

        /// <summary>Mean of the second and fourth edge lengths.</summary>
        public double Height => (Edge(1) + Edge(3)) / 2;

        /// <summary>Four edge lengths sorted, then two diagonal lengths sorted.</summary>
        public double[] Signature()
        {
            var edges = new List<double> { Edge(0), Edge(1), Edge(2), Edge(3) };
            edges.Sort();
            var diags = new List<double> { Corners[0].DistanceTo(Corners[2]), Corners[1].DistanceTo(Corners[3]) };
            diags.Sort();
            edges.AddRange(diags);
            return edges.ToArray();
        }
    }
}

