using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Betta.Attributes;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin
{
    [GrasshopperCollection("Facade", "Panels")]
    public interface IFacadePack : IBettaCollection
    {
        [GrasshopperMethod("Panelize Surface", "Divides a surface into four-sided panels", SubCategory = "Panels")]
        (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(
            [GrasshopperParameter("Surface")] Surface surface,
            [GrasshopperParameter("U Count", DefaultValue = 10)] int uCount,
            [GrasshopperParameter("V Count", DefaultValue = 6)] int vCount);

        [GrasshopperMethod("Panel Info", "Properties of one panel", SubCategory = "Panels")]
        (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(
            [GrasshopperParameter("Panel")] Panel panel);

        [GrasshopperMethod("Planarity", "Planarity deviation of each panel", SubCategory = "Analysis")]
        (List<double> Deviation, List<bool> Flat, int FlatCount) Planarity(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", DefaultValue = 0.5)] double tolerance,
            IBettaReport report);

        [GrasshopperMethod("Classify Panels", "Flat, cold-bent or custom by planarity deviation", SubCategory = "Analysis")]
        (List<string> Type, int FlatCount, int ColdBentCount, int CustomCount) ClassifyPanels(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", DefaultValue = 0.5)] double tolerance);

        [GrasshopperMethod("Panel Stats", "Area statistics of panels", SubCategory = "Analysis")]
        (double TotalArea, double MinArea, double MaxArea, double MeanArea) PanelStats(
            [GrasshopperParameter("Panels")] List<Panel> panels);

        [GrasshopperMethod("Group Identical Panels", "Groups panels with matching dimensions", SubCategory = "Fabrication")]
        (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", DefaultValue = 1.0)] double tolerance);

        [GrasshopperMethod("Nest On Sheets", "Shelf-nests panel rectangles onto sheets", SubCategory = "Fabrication")]
        Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Sheet Width", DefaultValue = 3000.0)] double sheetWidth,
            [GrasshopperParameter("Sheet Height", DefaultValue = 1500.0)] double sheetHeight,
            [GrasshopperParameter("Spacing", DefaultValue = 10.0)] double spacing,
            CancellationToken cancellationToken,
            IProgress<int> progress,
            IBettaReport report);

        [GrasshopperMethod("Cut List", "CSV of panel dimensions, optionally written to a file", SubCategory = "Fabrication")]
        (string CSV, bool Written) CutList(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Path", DefaultValue = "")] string path,
            [GrasshopperParameter("Write", DefaultValue = false)] bool write);
    }

    public class FacadePack : IFacadePack
    {
        public (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(Surface surface, int uCount, int vCount)
        {
            if (surface == null) throw new ArgumentException("Surface is missing");
            if (uCount < 1 || vCount < 1) throw new ArgumentException("U Count and V Count must be at least 1");

            var du = surface.Domain(0);
            var dv = surface.Domain(1);
            var pts = new Point3d[uCount + 1, vCount + 1];
            for (int i = 0; i <= uCount; i++)
                for (int j = 0; j <= vCount; j++)
                    pts[i, j] = surface.PointAt(
                        du.ParameterAt((double)i / uCount),
                        dv.ParameterAt((double)j / vCount));

            var panels = new List<Panel>();
            var outlines = new List<Curve>();
            for (int i = 0; i < uCount; i++)
                for (int j = 0; j < vCount; j++)
                {
                    var p = new Panel(pts[i, j], pts[i + 1, j], pts[i + 1, j + 1], pts[i, j + 1], i * vCount + j);
                    panels.Add(p);
                    outlines.Add(p.Outline);
                }
            return (panels, outlines);
        }

        public (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(Panel panel)
        {
            if (panel == null) throw new ArgumentException("Panel is missing");
            return (panel.Corners.ToList(), panel.Outline, panel.Area, panel.Center, panel.Index);
        }

        public (List<double> Deviation, List<bool> Flat, int FlatCount) Planarity(
            List<Panel> panels, double tolerance, IBettaReport report)
        {
            var dev = panels.Select(p => p.PlanarityDeviation).ToList();
            var flat = dev.Select(d => d <= tolerance).ToList();
            int flatCount = flat.Count(f => f);
            int notFlat = flat.Count - flatCount;
            if (notFlat * 2 > flat.Count)
                report.Warning($"{notFlat} of {flat.Count} panels are not flat");
            return (dev, flat, flatCount);
        }

        public (List<string> Type, int FlatCount, int ColdBentCount, int CustomCount) ClassifyPanels(
            List<Panel> panels, double tolerance)
        {
            var types = new List<string>();
            int flat = 0, cold = 0, custom = 0;
            foreach (var p in panels)
            {
                double d = p.PlanarityDeviation;
                if (d <= tolerance) { types.Add("flat"); flat++; }
                else if (d <= 10 * tolerance) { types.Add("cold-bent"); cold++; }
                else { types.Add("custom"); custom++; }
            }
            return (types, flat, cold, custom);
        }

        public (double TotalArea, double MinArea, double MaxArea, double MeanArea) PanelStats(List<Panel> panels)
        {
            if (panels == null || panels.Count == 0) throw new ArgumentException("No panels");
            var areas = panels.Select(p => p.Area).ToList();
            double total = areas.Sum();
            return (total, areas.Min(), areas.Max(), total / areas.Count);
        }

        public (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            List<Panel> panels, double tolerance)
        {
            var groups = new List<int>();
            var reps = new List<Panel>();
            var repSigs = new List<double[]>();
            foreach (var p in panels)
            {
                var sig = p.Signature();
                int found = -1;
                for (int g = 0; g < repSigs.Count && found < 0; g++)
                {
                    bool same = true;
                    for (int k = 0; k < 6; k++)
                        if (Math.Abs(sig[k] - repSigs[g][k]) > tolerance) { same = false; break; }
                    if (same) found = g;
                }
                if (found < 0)
                {
                    found = reps.Count;
                    reps.Add(p);
                    repSigs.Add(sig);
                }
                groups.Add(found);
            }
            return (groups, reps.Count, reps);
        }

        public Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            List<Panel> panels, double sheetWidth, double sheetHeight, double spacing,
            CancellationToken cancellationToken, IProgress<int> progress, IBettaReport report)
        {
            var input = panels?.ToList() ?? new List<Panel>();
            return Task.Run(() => Nest(input, sheetWidth, sheetHeight, spacing, cancellationToken, progress, report),
                cancellationToken);
        }

        private class Shelf { public double Y, Height, X; }

        private static (List<Curve>, List<int>, int, double) Nest(
            List<Panel> panels, double W, double H, double gap,
            CancellationToken ct, IProgress<int> progress, IBettaReport report)
        {
            var parts = panels.Select(p => (w: p.Width, h: p.Height)).OrderByDescending(t => t.h).ToList();
            var outlines = new List<Curve>();
            var sheets = new List<int>();
            var shelvesPerSheet = new List<List<Shelf>>();
            double placedArea = 0;
            int unplaced = 0;

            for (int n = 0; n < parts.Count; n++)
            {
                ct.ThrowIfCancellationRequested();
                progress?.Report((int)(100.0 * n / parts.Count));
                var (w, h) = parts[n];
                var sizes = new[] { (w, h), (h, w) };
                int sheet = -1;
                double px = 0, py = 0, pw = w, ph = h;
                bool placed = false;

                if (shelvesPerSheet.Count > 0)
                {
                    int s = shelvesPerSheet.Count - 1;
                    var shelves = shelvesPerSheet[s];
                    var shelf = shelves[shelves.Count - 1];
                    // current shelf
                    foreach (var (cw, ch) in sizes)
                    {
                        if (ch <= shelf.Height && shelf.X + cw + gap <= W)
                        {
                            sheet = s; px = shelf.X; py = shelf.Y; pw = cw; ph = ch;
                            shelf.X += cw + gap;
                            placed = true;
                            break;
                        }
                    }
                    // new shelf on the current sheet
                    if (!placed)
                    {
                        double y = shelf.Y + shelf.Height + gap;
                        foreach (var (cw, ch) in sizes)
                        {
                            if (gap + cw + gap <= W && y + ch + gap <= H)
                            {
                                shelves.Add(new Shelf { Y = y, Height = ch, X = gap + cw + gap });
                                sheet = s; px = gap; py = y; pw = cw; ph = ch;
                                placed = true;
                                break;
                            }
                        }
                    }
                }
                // new sheet
                if (!placed)
                {
                    foreach (var (cw, ch) in sizes)
                    {
                        if (gap + cw + gap <= W && gap + ch + gap <= H)
                        {
                            shelvesPerSheet.Add(new List<Shelf> { new Shelf { Y = gap, Height = ch, X = gap + cw + gap } });
                            sheet = shelvesPerSheet.Count - 1; px = gap; py = gap; pw = cw; ph = ch;
                            placed = true;
                            break;
                        }
                    }
                }
                if (!placed) { unplaced++; continue; }

                double ox = sheet * (W + 100);
                outlines.Add(new PolylineCurve(new[]
                {
                    new Point3d(ox + px, py, 0), new Point3d(ox + px + pw, py, 0),
                    new Point3d(ox + px + pw, py + ph, 0), new Point3d(ox + px, py + ph, 0),
                    new Point3d(ox + px, py, 0),
                }));
                sheets.Add(sheet);
                placedArea += pw * ph;
            }

            progress?.Report(100);
            if (unplaced > 0) report.Warning($"{unplaced} panels fit on no sheet");
            int count = shelvesPerSheet.Count;
            double util = count == 0 ? 0 : placedArea / (count * W * H);
            return (outlines, sheets, count, util);
        }

        public (string CSV, bool Written) CutList(List<Panel> panels, string path, bool write)
        {
            if (write && string.IsNullOrWhiteSpace(path)) throw new ArgumentException("Path is empty");
            var inv = CultureInfo.InvariantCulture;
            var sb = new StringBuilder("index,width,height,area,deviation\n");
            foreach (var p in panels)
                sb.Append(p.Index.ToString(inv)).Append(',')
                  .Append(p.Width.ToString("R", inv)).Append(',')
                  .Append(p.Height.ToString("R", inv)).Append(',')
                  .Append(p.Area.ToString("R", inv)).Append(',')
                  .Append(p.PlanarityDeviation.ToString("R", inv)).Append('\n');
            var csv = sb.ToString();
            if (!write) return (csv, false);
            File.WriteAllText(path, csv);
            return (csv, true);
        }
    }
}

